import Foundation
import HTTPTypes
import OpenAPIRuntime
import Synchronization
import Testing
@testable import LexidrawKit

private final class CompressionKey: TokenStore, @unchecked Sendable {
  var value: String?
  func load() throws -> String? { value }
  func save(_ token: String) throws { value = token }
  func delete() throws { value = nil }
}
private final class CompressionSpeech: URLProtocol, @unchecked Sendable {
  static let payload = Mutex(Data())
  override class func canInit(with request: URLRequest) -> Bool { true }
  override class func canonicalRequest(for request: URLRequest) -> URLRequest { request }
  override func startLoading() {
    guard request.url?.absoluteString == "https://openrouter.ai/api/v1/audio/speech" else { return }
    client?.urlProtocol(self, didReceive: HTTPURLResponse(url: request.url!, statusCode: 200, httpVersion: nil, headerFields: ["Content-Type": "audio/pcm"])!, cacheStoragePolicy: .notAllowed)
    client?.urlProtocol(self, didLoad: Self.payload.withLock { $0 })
    client?.urlProtocolDidFinishLoading(self)
  }
  override func stopLoading() {}
}
private final class CompressionCalls: Sendable { let value = Mutex(0) }
private struct CompressionApp: ClientTransport {
  let calls: CompressionCalls
  func send(_ request: HTTPRequest, body: HTTPBody?, baseURL: URL, operationID: String) async throws -> (HTTPResponse, HTTPBody?) {
    calls.value.withLock { $0 += 1 }
    return (HTTPResponse(status: .ok), nil)
  }
}
@Suite(.serialized) @MainActor struct CompressedDeviceAudioTests {
  private static let key = "opaque-delta-review-credential-7289991a"
  // Synthetic gzip, zlib and base64(gzip) credential echoes, not provider recordings.
  nonisolated private static let echoes = [
    "AAAfiwgAAAAAAAL/yy9ILCxN1U1JzSlJ1C1KLctMLddNLkpNSc0ryUzM0TU3srC0tDRMBACuIp+zJwAAAAA=",
    "eJzLL0gsLE3VTUnNKUnULUoty0wt100uSk1JzSvJTMzRNTeysLS0NEwEACmDDdUA",
    "SDRzSUFBQUFBQUFDLzhzdlNDd3NUZFZOU2MwcFNkUXRTaTNMVEMzWFRTNUtUVW5OSzhsTXpORTFON0t3dExRMFRBUUFyaUtmc3ljQUFBQT0="
,
    "",
    // A bounded PNG cannot grant an image exception inside encoded PCM.
    ""
  ]
  private func forged(_ samples: Data) throws -> DeviceAudio {
    var wav = try #require(Data(base64Encoded: DeviceAudio.pcm(Data([0, 0])).audio)).prefix(44)
    wav.append(samples)
    for (offset, number) in [(4, wav.count - 8), (40, samples.count)] {
      for shift in 0..<4 { wav[offset + shift] = UInt8((number >> (shift * 8)) & 255) }
    }
    return DeviceAudio(audio: wav.base64EncodedString(), seconds: Double(samples.count) / 48_000)
  }
  @Test(arguments: Self.echoes, [false, true])
  func compressedActiveAndRetiredEchoCannotPersistReopenOrDispatch(encoded: String, retired: Bool) async throws {
    let samples = try #require(Data(base64Encoded: encoded))
    CompressionSpeech.payload.withLock { $0 = samples }
    let config = URLSessionConfiguration.ephemeral
    config.protocolClasses = [CompressionSpeech.self]
    let runtime = NativeBYOK(store: CompressionKey(), configuration: config, narrationFixture: true)
    try runtime.replaceKey(Self.key)
    if retired { try runtime.replaceKey("another-synthetic-compression-credential") }
    let directory = FileManager.default.temporaryDirectory.appending(path: UUID().uuidString)
    defer { try? FileManager.default.removeItem(at: directory) }
    let files = NativeDeviceNarrationStore(directory: directory)
    let calls = CompressionCalls()
    let transport = CredentialGuardedTransport(underlying: CompressionApp(calls: calls))
    let save: (String, DeviceRecording) async throws -> String = { _, recording in
      _ = try await transport.send(HTTPRequest(method: .post, scheme: nil, authority: nil, path: "/recordings"), body: HTTPBody(JSONEncoder().encode(recording)), baseURL: URL(string: "https://app.test")!, operationID: "deviceNarration.save")
      return "saved"
    }
    let flow = NativeDeviceNarrationFlow(account: "alice", document: "doc", runtime: runtime, files: files, available: true, save: save)
    try await flow.start(text: "Hello")
    #expect(flow.checkpoint?.parts.allSatisfy { $0.kind != .completed } == true)
    await flow.sync()
    let reopen = NativeDeviceNarrationFlow(account: "alice", document: "doc", runtime: runtime, files: files, available: true, save: save)
    try reopen.restore()
    #expect(reopen.checkpoint?.parts.allSatisfy { $0.kind != .completed } == true)
    let output = try forged(samples)
    let checkpoint = DeviceNarrationCheckpoint(version: 1, account: "alice", document: "doc", id: "forged", created: Date(), status: "completed", parts: [.init(kind: .completed, text: "Hello", output: output)], fingerprints: try NativeCredentialGuard.shared.snapshot())
    let cleanDirectory = directory.appending(path: "forged")
    #expect(throws: NativeAIError.self) { try NativeDeviceNarrationStore(directory: cleanDirectory).save(checkpoint) }
    #expect(!FileManager.default.fileExists(atPath: cleanDirectory.appending(path: "checkpoint.json").path))
    await #expect(throws: NativeAIError.self) { _ = try await save("forged", try #require(checkpoint.recording)) }
    #expect(calls.value.withLock { $0 } == 0)
  }
}
